package cn.minidayz.patcher;
import org.json.*;import java.text.SimpleDateFormat;import java.util.*;
/** Persistent human-readable build evidence, independent of export status. */
public final class BuildView {
 public static String render(JSONObject r){if(r==null||r.length()==0)return "尚未运行检查。点击上方按钮后，这里显示步骤、文件差异和检查结论。";StringBuilder s=new StringBuilder();String state=r.optString("status");s.append(state.equals("running")?"进行中":state.equals("success")?"任务完成":state.equals("failed")?"任务失败":state.equals("cancelled")?"已取消":state.equals("interrupted")?"任务中断":state).append("\n");String prog=r.optString("progress");if(prog.length()>0)s.append("当前步骤进度：").append(prog).append("（不是整包总进度）\n");s.append("当前步骤：").append(r.optString("message",r.optString("stage","待开始"))).append("\n");if(r.has("started_ms")){long end=r.optLong("finished_ms",System.currentTimeMillis());s.append("耗时：").append(Math.max(0,(end-r.optLong("started_ms"))/1000)).append(" 秒\n");}s.append("\n分析结果\n");if(r.has("profile"))s.append("匹配档案：").append(r.optString("profile")).append("\n识别方式：").append(r.optString("match_mode").equals("exact")?"整包校验匹配":"逐文件内容匹配").append("\n");JSONObject analysis=r.optJSONObject("compatibility_analysis");if(analysis!=null){s.append("最接近档案：").append(analysis.optString("closest_profile")).append("\n");JSONObject d=analysis.optJSONObject("difference");if(d!=null){s.append("变化 ").append(d.optInt("changed")).append(" · 缺失 ").append(d.optInt("missing")).append(" · 新增 ").append(d.optInt("extra")).append("\n");JSONArray entries=d.optJSONArray("entries");if(entries!=null)for(int i=0;i<entries.length();i++){JSONObject e=entries.optJSONObject(i);String k=e.optString("kind");s.append(k.equals("changed")?"变更":k.equals("missing")?"缺失":"新增").append("：").append(e.optString("entry")).append("\n");}if(d.optBoolean("truncated"))s.append("其余差异请导出诊断查看。\n");}}if(r.has("error"))s.append("错误：").append(r.optString("error")).append("\n");JSONObject diagnosis=r.optJSONObject("diagnosis");if(diagnosis!=null)s.append("处理建议：").append(diagnosis.optString("action")).append("\n");if(r.optBoolean("signature_verified"))s.append("签名与归档校验通过，等待游戏实测。\n");else if(state.equals("success")&&r.has("profile"))s.append("兼容性检查通过，可继续生成 APK。\n");else if(state.equals("running"))s.append("正在检查，尚未得出最终结论。\n");s.append("\n步骤记录\n");JSONArray events=r.optJSONArray("events");SimpleDateFormat f=new SimpleDateFormat("HH:mm:ss",Locale.getDefault());if(events!=null)for(int i=0;i<events.length();i++){JSONObject e=events.optJSONObject(i);s.append(f.format(new Date(e.optLong("time_ms")))).append("  ").append(e.optString("message")).append("\n");}return s.toString();}
}
